@startuml

class User {
  + UserID : string
  + Name : string
  + Address : string
  + Birthday : date
}

class BusinessOwner extends User {
  + LinkedInAccount : string
}

class HungryCustomer extends User {
  + DeliveryAddress : string
}

class Entertainer extends User {
  + StageName : string
  + Bio : string
  + PricePer30Minutes : float
}

class PizzaRestaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : string
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : float
}

class Order {
  + OrderID : string
  + DateTime : datetime
  + LatestDeliveryTime : time
  + NumberOfPeople : int
}

class EntertainmentOrder extends Order {
  + EntertainmentType : string
  + Duration : int
}

class EntertainerAvailability {
  + Day : string
}

BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
HungryCustomer "1" -- "*" Order : makes
Order "*" -- "1..*" Pizza : contains
Entertainer "1" -- "*" EntertainmentOrder : fulfills
Entertainer "1" -- "*" EntertainerAvailability : has
EntertainerAvailability "*" -- "1" PizzaRestaurant : for
PizzaRestaurant "1" -- "*" Pizza : provides

@enduml

